    el.querySelectorAll('[data-rrg]').forEach((b) => b.addEventListener('click', () => { const r = rrgRows(G, mk).find((x) => x.slug === b.dataset.rrg); if (r && b.dataset.rrg) wChart(b.dataset.rrg, mk, 'group_w_charts', indTv(r, mk)); }));
