  const D = state.gpCh[mk]; const g = D && D[kind] && D[kind][key]; const box = $('#mxc'); const pb = $('#mxcp'); if (!box) return;
  if (!g) { box.innerHTML = '<p class="muted pad">Chart appears after the next nightly run.</p>'; return; }
