  const opt = light ? { ...base, layout: { ...base.layout, background: { color: '#FFFFFF' }, textColor: '#374151' }, grid: { vertLines: { color: '#F3F4F6' }, horzLines: { color: '#EEF0F4' } },
    rightPriceScale: { borderColor: '#E5E7EB' } } : base;
