  seg(r2, '#16A34A', '2R target', 2); seg(t.entry, '#7C3AED', 'entry', 0, 3); seg(s0, '#DC2626', 'first SL', 2);
  const sl = t.stop_last != null ? t.stop_last : (t.exit ? null : t.stop);   // open holdings: the stop now
