  const bySec = state.mxSort === 'sec';
  rows.sort((a, b) => (bySec ? (so(a) - so(b)) || (rs(b) - rs(a)) || (b.sc - a.sc) : (b.sc - a.sc) || (b.n - a.n) || (so(a) - so(b)) || (rs(b) - rs(a))) || (b.buy - a.buy) || (a.sym < b.sym ? -1 : 1));
  const cols = S.cols.filter(([k]) => rows.some((x) => x.o[k]));
