  const invFirst = ((fund && fund.rows) || []).filter((r) => (r.market || 'IN') === fm && r.mclose).map((r) => ({ name: fundName(r), a: r.mclose, close: r.close, row: r }))
    .concat(mk === 'NSE' ? ((idx && idx.rows) || []).map((r) => ({ name: r.index, a: r, close: r.close, tv: nseIdxTv(r.index) })) : []);
