  const tuShow = [...tuNew, ...tuEx, ...tuIn.filter((r) => !r.new), ...TU.filter((r) => r.status === 'flat' && r.dist_pct <= 3).sort((a, b) => a.dist_pct - b.dist_pct).slice(0, 3)];
