  const ind = (G.rows || []).filter((x) => x.n >= 3).sort((a, b) => b.p1m - a.p1m)[0];
  const th = (G.themes || []).filter((x) => x.n >= 3).sort((a, b) => b.p1m - a.p1m)[0];
  const sg = (v) => `${v >= 0 ? '+' : '−'}${fmt(Math.abs(v), 1)}%`;
