async function tdRiskCard(box, S0) {
  if (!box) return;
  let S = S0 || null; const c = lvCfg();
  if (!S0 && c.url && c.token) {
    let cached = null; try { cached = JSON.parse(localStorage.getItem('td.riskS') || 'null'); } catch (e) { /* */ }
    if (cached && cached.trades) { S = cached; S._cached = true; }
    lvPlan().then((F) => { if (!F || !F.trades || !box.isConnected) return;
      try { localStorage.setItem('td.riskS', JSON.stringify({ capital: F.capital, trades: F.trades, at: Date.now() })); localStorage.setItem('td.heldSyms', JSON.stringify((F.holdings || []).filter((h) => h.qty > 0).map((h) => h.symbol))); } catch (e) { /* */ }
      if (state._tdMkNow === 'NSE') tdApplyHeld('NSE');
      tdRiskCard(box, F); }).catch(() => {});
    if (!S) { box.innerHTML = '<div class="td-risk"><p class="muted td-rs">Loading your open risk and return from your server…</p></div>'; const m = $('#tdmini'); if (m) m.innerHTML = '<div class="td-mini"><span><small>Loading open risk and return…</small></span></div>'; return; }
  }
  let pos = [], C = cap('NSE') || 50000, src = 'practice';
  if (S && S.trades) { src = 'your account'; C = S.capital || C;
    pos = S.trades.filter((t) => t.state === 'open' && t.qty).map((t) => ({ symbol: t.symbol, qty: t.qty, entry: t.entry, now: t.ltp || t.entry, line: t.trail_level || t.stop, stop: t.gtt_trigger || t.stop, trail_at: t.trail_at, trail_prev: t.trail_prev, new_stop: t.gtt_trigger })); }
  else { const px = (await pfPrices().catch(() => ({ px: {} }))).px || {};
    pos = bgPractice().filter((t) => t.state === 'open' && t.qty && t.entry).map((t) => ({ symbol: t.symbol, qty: t.qty, entry: t.entry, now: (px[t.symbol] || [])[0] || t.entry, line: t.stop, stop: t.stop })); }
  /* 11 Nov 2026: two numbers. "Open risk" = down to each system's own exit line (Momentum 30-week SMA, Trend EMA 21, others
     their plan stop) — where the system actually sells, on a close. "Worst case" = down to the crash-guard GTTs (15% below
     that line). Plus the open trades' return so far. No 6% rule: capping heat at 6% cut the tested return from 23% to 11%/yr. */
  const atRisk = pos.reduce((a, p) => a + p.qty * Math.max(0, p.now - (p.line || p.stop)), 0); const pct = C ? atRisk / C * 100 : 0;
  const worst = pos.reduce((a, p) => a + p.qty * Math.max(0, p.now - p.stop), 0);
  const cost = pos.reduce((a, p) => a + p.qty * (p.entry || p.now), 0), pnl = pos.reduce((a, p) => a + p.qty * (p.now - (p.entry || p.now)), 0), rp = cost ? pnl / cost * 100 : 0;
  const wk = new Date(Date.now() - 7 * 864e5).toISOString().slice(0, 10);
  const raised = pos.filter((p) => p.trail_at && String(p.trail_at).slice(0, 10) >= wk && p.new_stop);
  const mini = $('#tdmini'); if (mini && pos.length) {
    const mr = (p, col) => `<svg viewBox="0 0 36 36" width="54" height="54" aria-hidden="true"><circle cx="18" cy="18" r="14" fill="none" style="stroke:var(--line)" stroke-width="4.5"/><circle cx="18" cy="18" r="14" fill="none" style="stroke:${col}" stroke-width="4.5" stroke-linecap="round" stroke-dasharray="${(Math.min(1, p / 20) * 88).toFixed(1)} 88" transform="rotate(-90 18 18)"/></svg>`;
    mini.innerHTML = `<button class="td-mini" aria-label="Open risk and return, details below">${mr(pct, 'var(--saffron)')}<span><b>${fmt(pct, 1)}%</b><small>open risk</small></span>${mr(Math.abs(rp), rp >= 0 ? 'var(--rise)' : 'var(--fall)')}<span><b class="${rp >= 0 ? 'up' : 'down'}">${rp >= 0 ? '+' : '−'}${fmt(Math.abs(rp), 1)}%</b><small>return · ${pnl >= 0 ? '+' : '−'}${inr(Math.abs(pnl))}</small></span><i>›</i></button>`;
    mini.querySelector('button').addEventListener('click', () => { const d = box.querySelector('details'); if (d) d.open = true; box.scrollIntoView({ behavior: 'smooth', block: 'start' }); });
  }
  /* 12 Nov 2026: the rings live once, at the top (#tdmini). This card is the explanation behind them. Without open trades
     the top strip stays empty, so the card says so. */
  box.innerHTML = `<details class="td-risk td-riskd"${pos.length ? '' : ' open'}><summary><span><b>Open risk ${fmt(pct, 1)}% · return ${rp >= 0 ? '+' : '−'}${fmt(Math.abs(rp), 1)}%</b><small>What these numbers mean</small></span></summary>
    <p class="muted td-rs">${pos.length ? `<b>Open risk:</b> if every stock closed at its system's exit line, about −${inr(atRisk)} (${fmt(pct, 1)}% of ${src}) across ${pos.length} ${pos.length === 1 ? 'trade' : 'trades'}. Worst case, if prices gapped down to the crash-guard GTTs: −${inr(worst)} (${fmt(C ? worst / C * 100 : 0, 1)}%).<br><b>Return so far:</b> ${pnl >= 0 ? '+' : '−'}${inr(Math.abs(pnl))} on ${inr(cost)} in these trades, as of ${new Date().toLocaleDateString('en-GB', { day: 'numeric', month: 'short' })}.` : `No open trades in ${src} yet.`}</p></details>
    ${raised.map((p) => `<div class="td-card td-raise"><span class="td-av" style="background:var(--rise)">↑</span><span class="td-nm"><b>Stop raised to ${inr(p.new_stop, 0)}</b><small>${esc(p.symbol)}${p.trail_prev ? ` · from ${inr(p.trail_prev, 0)}` : ''} · trailing stop, updated daily</small></span></div>`).join('')}`;
}
