/* 22 Nov 2026 (Amritpal: "add a search lens - search any asset or stock and see which systems are activated on it"). Every market's
   stocks (group_pulse + weekly data) and every ETF (funds.json); the check lists each system with its status, the Live plan, the
   top-down context (industry rotation, results season, the stock's own rotation, 6-month sector tag) and a 1-year chart. */
async function searchIndex() {
  if (state.sIdx) return state.sIdx;
  const out = [], seen = new Set();
  const add = (sym, name, mk, kind, key) => { const id = mk + ':' + sym + ':' + kind; if (!sym || seen.has(id)) return; seen.add(id); out.push({ sym, name: name || '', mk, kind, key }); };
  for (const mk of ['NSE', 'US', 'ASX', 'UK']) {
    const [G, W] = await Promise.all([loadGP(mk).catch(() => null), wkLoad(mk)]);
    const nm = {};
    if (G) { ((G.nse || {}).rows || []).concat(G.rows || []).concat(G.themes || []).forEach((r) => (r.members || []).forEach((m) => { nm[m.symbol] = nm[m.symbol] || m.name; })); }
    Object.keys((W && W.s) || {}).concat(Object.keys((G && G.stock) || {})).forEach((sym) => add(sym, nm[sym], mk, 'stock'));
  }
  if (!state.fund) state.fund = await getJSON(MAIN + 'data/scan/funds.json', 'funds').catch(() => null);
  const FM = { IN: 'NSE', US: 'US', AU: 'ASX', UK: 'UK' };
  ((state.fund || {}).rows || []).forEach((r) => { const sym = String(r.key).split(':').pop().replace(/\.L$/, ''); add(sym, r.name, FM[r.market] || 'US', r.kind === 'etf' ? 'ETF' : (r.kind || 'fund'), r.key); });
  return (state.sIdx = out);
}
/* 23 Nov 2026 (Amritpal: "easy search for a sector, industry or theme - show its stocks with any system active, and the strength or
   Pulse of the industry or sector"): India groups searchable by name. Sector Pulse = its industries' Pulse weighted by liquid stocks. */
function groupIndex(G) {
  if (!G) return []; if (G._gidx) return G._gidx; const out = [];
  const nr = (G.nse && G.nse.rows) || []; const liqOf = (r) => r.members.filter((m) => m.liquid).map((m) => m.symbol);
  const rankI = nr.filter((r) => r.p1m != null && (r.n_liquid || 0) >= 3).sort((a, b) => b.p1m - a.p1m).map((r) => r.basic);
  nr.forEach((r) => out.push({ kind: 'Industry', name: r.basic, members: r.members.map((m) => m.symbol), p1m: r.p1m, p1w: r.p1w, p1q: r.p1q, q: (r.rrg || {}).now, r1m: r.r1m, r3m: r.r3m, nl: r.n_liquid,
    rank: rankI.indexOf(r.basic) + 1 || null, of: rankI.length, sub: r.industry }));
  ((G.nse && G.nse.sectors) || []).forEach((sx) => { const R = nr.filter((r) => r.sector === sx.sector);
    const w = R.reduce((a, r) => a + (r.p1m != null ? (r.n_liquid || 1) : 0), 0); const wa = (k) => (w ? R.reduce((a, r) => a + (r.p1m != null && r[k] != null ? r[k] * (r.n_liquid || 1) : 0), 0) / w : null);
    const p = wa('p1m');
    out.push({ kind: 'Sector', name: sx.sector, members: R.flatMap((r) => r.members.map((m) => m.symbol)), p1m: p, p1w: wa('p1w'), p1q: wa('p1q'), q: (sx.rrg || {}).now, r1m: sx.r1m, r3m: sx.r3m, sub: `${sx.industries} industries` }); });
  (G.themes || []).forEach((t) => out.push({ kind: 'Theme', name: t.group, members: t.members.map((m) => m.symbol), p1m: t.p1m, p1w: t.p1w, p1q: t.p1q, q: (t.rrg || {}).now, r1m: null, r3m: null,
    rank: t.rank, of: (G.themes || []).length, sub: t.index || '' }));
  (G.rows || []).forEach((r) => out.push({ kind: 'Group', name: r.group, members: (r.members || []).map((m) => m.symbol || m), p1m: r.p1m, q: (r.rrg || {}).now, r1m: r.r1m, r3m: null,
    rank: r.rank, of: (G.rows || []).length, sub: r.sector || '' }));
  G._gidx = out; return out;
}
function groupHit(G, q) {
  const w = String(q || '').toLowerCase().replace(/[^a-z0-9& ]+/g, ' ').trim().split(/\s+/).filter((x) => x.length >= 2 && !['and', 'the', 'stocks', 'sector', 'industry', 'theme'].includes(x));
  if (!w.length) return [];
  const AL = { psu: ['public sector', 'psu', 'cpse'], psb: ['public sector'], it: ['information technology', 'software', 'it '], fmcg: ['fast moving', 'fmcg'], auto: ['auto'],
    pvt: ['private'], nbfc: ['non banking', 'nbfc'], realty: ['realty', 'residential'], metal: ['metal', 'steel', 'aluminium'], defence: ['defen'], railway: ['rail'], ev: ['electric vehicle', ' ev'] };
  return groupIndex(G).filter((g) => { const n = ' ' + (g.name + ' ' + (g.sub || '')).toLowerCase() + ' '; return w.every((x) => n.includes(x) || (AL[x] || []).some((y) => n.includes(y))); })
    .sort((a, b) => ['Sector', 'Industry', 'Theme', 'Group'].indexOf(a.kind) - ['Sector', 'Industry', 'Theme', 'Group'].indexOf(b.kind) || (b.p1m || 0) - (a.p1m || 0)).slice(0, 8);
}
function groupOpen(g) {
  state._grp = g;
  const bits = [`${g.kind}${g.sub ? ' (' + g.sub + ')' : ''}`, g.p1m != null ? `Pulse ${fmt(g.p1m, 0)}%${g.rank ? ` · #${g.rank} of ${g.of}` : ''}` : null, g.q ? `rotation ${g.q}` : null,
    g.r1m != null ? `1 month ${g.r1m >= 0 ? '+' : ''}${fmt(g.r1m, 1)}%` : null, g.r3m != null ? `3 months ${g.r3m >= 0 ? '+' : ''}${fmt(g.r3m, 1)}%` : null].filter(Boolean);
  sysListView({ id: 'grp', name: g.name, d: bits.join(' · '), ok: 1, nse: 1 }, 'NSE', g.name);
}
/* 23 Nov 2026 (Amritpal: "a page where all sectors, industries and themes are listed, and as they move up or down in strength it
   shows moving up or moving down - infographic"): Strength board. Pulse = share of a group's liquid stocks trending, averaged over
   a quarter (Q), a month (M) and the last week (W). The slope Q → M → W shows the direction; "moving up" = this week at least 5
   points above the month, "moving down" = 5 below. Rank move = places gained this week vs the month ranking. Context, not a signal. */
// 23 Nov 2026 (Amritpal: "fading to dark green, yellow, red"): heat colour from this week's strength - red (weak) -> yellow -> dark green (strong)
const sbKind = () => { try { return localStorage.getItem('sb.kind') || 'Index'; } catch (e) { return 'Index'; } };
function sbHeat(p) {
  const v = Math.max(0, Math.min(100, p || 0)); const h = Math.round(v * 1.25); const l = Math.round(46 - Math.max(0, v - 50) * 0.28);
  return `--sbh:hsl(${h} 72% ${l}%);background:linear-gradient(90deg, hsl(${h} 72% ${l}% / .38), hsl(${h} 72% ${l}% / .08) 70%), var(--card);border-left-color:hsl(${h} 72% ${l}%)`;
}
