  const rM = rk('p1m'), rW = rk('p1w');
  all.forEach((g) => { g.dW = g.p1w - g.p1m; g.dQ = g.p1q != null ? g.p1m - g.p1q : null; g.mv = (rM[g.name] || 0) - (rW[g.name] || 0);
    g.dir = kind === 'Index' ? (g.rsd >= 0.75 ? 'up' : g.rsd <= -0.75 ? 'down' : 'flat') : g.dW >= 5 ? 'up' : g.dW <= -5 ? 'down' : 'flat'; });
