    const [GM, ER] = await Promise.all([getJSON(MAIN + 'data/scan/growth_mom.json', 'growthmom').catch(() => null), getJSON(MAIN + 'data/scan/etf_rotation.json', 'etf_rotation').catch(() => null)]);
