/* ------------------------------------------------------------------ Search by system (22 Nov 2026)
   Amritpal: "In search I should be able search stocks or assets by system like day cup breakout weekly cup or flag I mean all
   systems". Typing a system's name (or a word of it) in Search lists the matching systems first; tapping one lists every stock or
   ETF that system has on today, in India / US / Australia / UK, strongest top-down first (same order as Strategies). */
const SYSX = [
  { id: 'ath', name: 'ATH breakout (Momentum)', d: 'Monthly all-time-high breakout after a long base', a: 'ath all time high alltime momentum monthly breakout mom', ok: 1 },
  { id: 'mo', name: 'Month cup close', d: 'Month closed above the all-time high', a: 'month monthly cup close ath breakout', ok: 1 },
  { id: 'wk', name: 'Week cup close', d: 'Week closed above the all-time high', a: 'week weekly cup close ath breakout', ok: 1 },
  { id: 'dy', name: 'Day cup close', d: 'Day closed above the all-time high', a: 'day daily cup close ath breakout', ok: 1 },
  { id: 'tf', name: 'Cup 9/21', d: 'Cup breakout bought with the 9/21 rules', a: 'cup 921 9 21 cup921 trend breakout', ok: 1 },
  { id: 't921', name: '9/21 trend', d: 'Fresh 9/21 cross with a rising 50-day average', a: '921 9 21 nine twenty trend ema cross', ok: 1 },
  { id: 'ipo', name: 'IPO cup', d: 'Recent listing breaking out of its first base', a: 'ipo cup new listing listed breakout', ok: 1 },
  { id: 'gm', name: 'Growth + momentum', d: 'Fast-growing profits and strong price', a: 'growth momentum gm g+m earnings', ok: 1 },
  { id: 'tb', name: 'Tight base', d: '10 sessions within 12% at the 20-day average, drying volume', a: 'tight base breakout squeeze consolidation', ok: 0 },
  { id: 'vcp', name: 'VCP', d: 'Volatility contraction: each pullback smaller', a: 'vcp volatility contraction squeeze tight base minervini', ok: 0 },
  { id: 'fl', name: 'Flags & pennants', d: 'Uptrend, 15%+ pole, tight flag on drying volume, breakout on 1.5× volume', a: 'flag flags bull bullish pennant pennants pendant rectangle box pole continuation', ok: 0 },
  { id: 'pt', name: 'Bottoming out', d: 'W, tilted W, triple bottom, inverse head & shoulders', a: 'bottom bottoming w double triple tilted inverse head shoulders ihs reversal', ok: 0 },
  { id: 'rt', name: 'Support retest', d: 'Back at an old breakout level', a: 'retest support pullback old breakout', ok: 0 },
  { id: 'st', name: 'MA stack', d: 'Close above 20 > 50 > 100 > 200-day averages, all rising', a: 'ma stack moving average averages 20 50 100 200 aligned', ok: 0 },
  { id: 'etf', name: 'ETF ATH system', d: 'ETF month close above its all-time high after a 1-year base', a: 'etf etfs fund funds ath month close investment', ok: 1 },
  { id: 'gov', name: 'Govt focus', d: 'Industries the government is pushing (PM at FICCI, 19 Nov 2026): APIs, steel, metals, agri, tools, machinery', a: 'govt government focus policy pm modi speech ficci msme make india atmanirbhar self reliant swadeshi export news clue clues report cabinet fdi duty pli', ok: 1, nse: 1 },
  { id: 'rot', name: 'ETF rotation', d: 'Monthly: hold the strongest of Nifty, Midcap, Gold, Nasdaq or cash', a: 'etf rotation rotate monthly gold nifty nasdaq midcap liquid', ok: 1, nse: 1 }];
const SYS_STOP = new Set(['system', 'systems', 'stock', 'stocks', 'pattern', 'patterns', 'setup', 'setups', 'list', 'the', 'all', 'in', 'on', 'show', 'me', 'with', 'and', 'of', 'a']);
const sysNorm = (s) => String(s).toLowerCase().replace(/[^a-z0-9+]+/g, ' ').trim();
function sysMatch(q) {
  const raw = sysNorm(q); if (raw.length < 2) return [];
  const qw = raw.split(' ').filter((w) => w && !SYS_STOP.has(w)); if (!qw.length) return [];
  const qc = qw.join('');
  const r = SYSX.map((s) => { const words = sysNorm(s.name + ' ' + s.a).split(' '); const comp = sysNorm(s.name).replace(/ /g, '');
    const hit = qw.filter((w) => words.some((x) => x.startsWith(w) || (w.length >= 4 && x.startsWith(w.slice(0, -1))))).length;   // "flag" ~ "flags"
    const sc = comp === qc ? 100 : comp.startsWith(qc) ? 50 : hit === qw.length ? 20 + hit : hit && qw.length > 1 ? hit : 0;
    // name words count double so "day cup" ranks Day cup first, "weekly cup" ranks Week cup first
    const nm = sysNorm(s.name).split(' '); const nb = qw.filter((w) => nm.some((x) => x.startsWith(w) || w.startsWith(x) && x.length >= 3)).length;
    return { s, sc: sc ? sc + nb * 3 : 0, full: hit === qw.length }; }).filter((x) => x.sc > 0 && (x.sc >= 20 || qw.length > 1));
  const L = r.some((x) => x.full) ? r.filter((x) => x.full) : r;   // every word matched beats a partial match
  return L.sort((a, b) => b.sc - a.sc).map((x) => x.s);
}
async function sysRows(s, mk, q) {
  const MP = MAIN + MKT[mk].path; const qn = sysNorm(q || '');
  if (['ath', 'mo', 'wk', 'dy', 't921', 'ipo', 'gm', 'tb', 'vcp'].includes(s.id)) {
    const S = await sysMap(mk).catch(() => null); if (!S) return [];
    // 22 Nov 2026 (Amritpal: "add currency pairs to all systems"): month / week / day cup closes also list the assets.json rows -
    // currency pairs, commodities, coins, world indices - which the asset scan already checks with the same rules (watch only)
    const ak = { mo: 'mclose', wk: 'wclose', dy: 'dclose' }[s.id]; let AS = [];
    if (ak) { if (!state.assets) state.assets = await getJSON(MAIN + 'data/scan/assets.json', 'assets').catch(() => null);
      const fx = /currenc|forex|\bfx\b|pair/.test(qn);
      AS = ((state.assets && state.assets.rows) || []).filter((r) => r[ak] && (!fx || r.group === 'Currencies')).map((r) => ({ sym: r.name, asset: r, name: r.group === 'Currencies' ? 'Currency' : r.group, sc: 1, st: `${r.group === 'Currencies' ? 'currency pair' : r.group.toLowerCase()} · ${s.id === 'mo' ? 'month' : s.id === 'wk' ? 'week' : 'day'} closed above its high (watch)` })); }
    if (AS.length && /currenc|forex|\bfx\b|pair/.test(qn)) return AS;
    return AS.concat(Object.keys(S.M).filter((sym) => S.M[sym][s.id]).map((sym) => { const o = S.M[sym][s.id]; return { sym, st: o.txt === '✓' ? 'on the list' : o.txt, sc: 3 - o.lvl, buy: o.lvl === 0 }; }));
  }
  if (s.id === 'st') { const S = await sysMap(mk).catch(() => null); return S ? [...S.STK].map((sym) => ({ sym, st: 'stacked', sc: 0 })) : []; }
  if (['tf', 'rt'].includes(s.id)) {
    const P = await getJSON(MP + 'trade_plan.json', mk === 'NSE' ? 'trade_plan' : 'tp_' + mk).catch(() => null);
    return ((P && (P.top || []).concat(P.swing || [], P.more || [])) || []).filter((r) => bkOf(r) === s.id)
      .map((r) => ({ sym: r.symbol, st: s.id === 'rt' ? 'at old breakout' : r.trigger ? `waiting · above ${fmt(r.trigger, 2)}` : 'Buy', sc: r.score || 0, buy: s.id === 'tf' && !r.trigger }));
  }
  if (s.id === 'grp') {     // 23 Nov 2026: a sector / industry / theme from search - every member, on-system ones first
    const g = state._grp; if (!g) return [];
    const [S, plan, FL, PT] = await Promise.all([sysMap('NSE').catch(() => null), getJSON(MP + 'trade_plan.json', 'trade_plan').catch(() => null),
      getJSON(MP + 'flags.json', 'flags_NSE').catch(() => null), getJSON(MP + 'patterns.json', 'patterns').catch(() => null)]);
    const fl = {}; ((FL && FL.rows) || []).forEach((x) => { fl[x.symbol] = x; }); const pt = {}; ((PT && PT.rows) || []).forEach((x) => { pt[x.symbol] = x; });
    const out = [];
    for (const sym of g.members) {
      const a = await sysActive('NSE', sym, S, plan); const L = a.list.filter((x) => x.n !== 'Stack' && !/ · off$/.test(x.n));
      if (fl[sym]) L.push({ n: fl[sym].status === 'breakout' ? 'Flag · broke out' : 'Flag', c: fl[sym].status === 'breakout' ? 'buy' : 'near' });
      if (pt[sym]) L.push({ n: pt[sym].status === 'breakout' ? 'Bottom · broke out' : 'Bottoming', c: pt[sym].status === 'breakout' ? 'buy' : 'near' });
      out.push({ sym, nsys: L.length, buy: L.some((x) => x.c === 'buy'), sc: 0, st: L.length ? `${L.length} system${L.length > 1 ? 's' : ''}: ${L.map((x) => x.n).join(', ')}` : 'no system now' });
    }
    return /\ball\b/.test(qn) || !out.some((x) => x.nsys) ? out : out.filter((x) => x.nsys).concat(out.filter((x) => !x.nsys).map((x) => ({ ...x, st: 'no system now' })));
  }
  if (s.id === 'gov') {
    if (mk !== 'NSE') return []; const G = await govLoad().catch(() => null); const GP = await loadGP('NSE').catch(() => null); if (!G || !GP || !GP.nse) return [];
    const msme = /msme|small/.test(qn);
    const onlyN = /news|clue|report/.test(qn), all = /\ball\b|every/.test(qn);
    // 22 Nov 2026 (Amritpal: "a lot of stocks with news and govt focus - how do we shortlist those that satisfy most of our systems"):
    // each stock is checked against every system (trade plan, ATH / cup closes, 9/21, IPO, growth+momentum, tight base, VCP, flags,
    // bottom patterns); the list keeps only stocks on at least one system (type "govt all" for everyone), most systems first.
    const [S, plan, FL, PT] = await Promise.all([sysMap('NSE').catch(() => null), getJSON(MP + 'trade_plan.json', 'trade_plan').catch(() => null),
      getJSON(MP + 'flags.json', 'flags_NSE').catch(() => null), getJSON(MP + 'patterns.json', 'patterns').catch(() => null)]);
    const fl = {}; ((FL && FL.rows) || []).forEach((x) => { fl[x.symbol] = x; }); const pt = {}; ((PT && PT.rows) || []).forEach((x) => { pt[x.symbol] = x; });
    const rows = [];
    for (const r of GP.nse.rows) { const th = onlyN ? [] : govThemes(r.basic); const nw = govNews(r.basic); if (!th.length && !nw.length) continue;
      for (const m of r.members) { const g = govOf(m.symbol); const a = await sysActive('NSE', m.symbol, S, plan); const L = a.list.filter((x) => x.n !== 'Stack' && !/ · off$/.test(x.n));   // MA stack is shown, not scored; switched-off buckets don't count
        if (fl[m.symbol]) L.push({ n: fl[m.symbol].status === 'breakout' ? 'Flag · broke out' : 'Flag', c: fl[m.symbol].status === 'breakout' ? 'buy' : 'near' });
        if (pt[m.symbol]) L.push({ n: pt[m.symbol].status === 'breakout' ? 'Bottom · broke out' : 'Bottoming', c: pt[m.symbol].status === 'breakout' ? 'buy' : 'near' });
        const why = th.map((t) => t.name).join(' · ') || (nw[0] ? `${nw[0].official ? 'Official' : 'Report'}: ${nw[0].title.slice(0, 60)}` : '');
        rows.push({ sym: m.symbol, nsys: L.length, buy: L.some((x) => x.c === 'buy'), sc: (m.liquid ? 1 : 0), msme: g && g.msme,
          st: (L.length ? `${L.length} system${L.length > 1 ? 's' : ''}: ${L.map((x) => x.n).join(', ')} · ` : '') + why + (g && g.msme ? ' · MSME' : '') }); } }
    return rows.filter((x) => (!msme || x.msme) && (all || x.nsys > 0));
  }
  if (s.id === 'fl') {
    const F = await getJSON(MP + 'flags.json', 'flags_' + mk).catch(() => null);
    const only = /pennant|pendant/.test(qn) ? 'Pennant' : /rectangle|box/.test(qn) ? 'Rectangle' : null;
    return ((F && F.rows) || []).filter((x) => !only || x.shape === only).map((x) => ({ sym: x.symbol, fl: x, buy: x.status === 'breakout', sc: x.status === 'breakout' ? 2 : 1,
      pri: (x.shape === 'Rectangle' ? 2 : 0) + (x.lane === 'established' ? 1 : 0), name: x.kind && x.kind !== 'stock' ? (x.kind === 'index' ? 'Index' : 'Asset') : '',
      st: `${x.shape} · ${x.lane === 'early' ? 'new uptrend' : 'uptrend'} · ${x.status === 'breakout' ? 'broke out' + (x.days_since ? ' ' + x.days_since + 'd ago' : ' today') : 'buy above ' + fmt(x.trigger, 2)}` }));
  }
  if (s.id === 'pt') {
    const T = await getJSON(MP + 'patterns.json', mk === 'NSE' ? 'patterns' : 'patterns_' + mk).catch(() => null); const TYP = { DB: 'W bottom', TW: 'Tilted W', TB: 'Triple bottom', IHS: 'Inv H&S' };
    const only = /triple/.test(qn) ? 'TB' : /inverse|head|ihs/.test(qn) ? 'IHS' : /tilt/.test(qn) ? 'TW' : /\bw\b|double/.test(qn) ? 'DB' : null;
    return ((T && T.rows) || []).filter((x) => !only || x.typ === only).map((x) => ({ sym: x.symbol, sc: x.status === 'breakout' ? 1 : 0, pt: x, name: x.kind && x.kind !== 'stock' ? (x.kind === 'index' ? 'Index' : 'Asset') : '',
      st: `${TYP[x.typ] || x.typ || x.pattern || ''} · ${x.status === 'breakout' ? 'broke out' : x.to_neck_pct != null ? fmt(x.to_neck_pct, 1) + '% to go' : x.status || ''}` }));
  }
  if (s.id === 'etf') {
    if (!state.fund) state.fund = await getJSON(MAIN + 'data/scan/funds.json', 'funds').catch(() => null);
    const FM = { NSE: 'IN', US: 'US', ASX: 'AU', UK: 'UK' };
    return ((state.fund || {}).rows || []).filter((f) => f.market === FM[mk] && ((f.ath && f.ath.status === 'open') || f.mclose || f.wclose))
      .map((f) => ({ sym: String(f.key).split(':').pop().replace(/\.L$/, ''), name: f.name, fund: f, buy: !!f.mclose && !(f.ath && f.ath.status === 'open'), sc: f.mclose ? 2 : f.ath ? 1 : 0,
        st: f.ath && f.ath.status === 'open' ? 'in a trade' : f.mclose ? 'month closed above ATH: buy' : 'week closed above ATH (watch)' }));
  }
  if (s.id === 'rot') {
    if (mk !== 'NSE') return [];
    const R = await getJSON(MAIN + 'data/scan/etf_rotation.json', 'etf_rot').catch(() => null); const c = R && R.current; if (!c) return [];
    const hold = new Set(c.hold || []); const nm = R.names || {};
    return [...hold].map((sym) => ({ sym, name: nm[sym], st: `hold this month (${c.month})`, sc: 9, buy: true, etfOnly: 1 }))
      .concat((c.ranks || []).filter((r) => !hold.has(r.sym)).map((r) => ({ sym: r.sym, name: nm[r.sym], st: `not held · 3 months ${r.ret_3m_pct >= 0 ? '+' : '−'}${fmt(Math.abs(r.ret_3m_pct), 1)}%`, sc: 0, etfOnly: 1 })));
  }
  return [];
}
async function sysListView(s, mk, q) {
  mk = s.nse ? 'NSE' : mk || tdMk();
  openPanel('<p class="muted pad">Listing stocks…</p>');
  const [rows, X] = await Promise.all([sysRows(s, mk, q), t3Ctx(mk).catch(() => null)]);
  const Pq = { L: 3, I: 2, W: 1, G: 0, N: -1 };
  rows.forEach((x) => { const nonStk = !!x.asset || (x.fl && x.fl.kind && x.fl.kind !== 'stock') || (x.pt && x.pt.kind && x.pt.kind !== 'stock'); if (nonStk) x.name = x.name || (x.fl ? (x.fl.kind === 'index' ? 'Index' : 'Asset') : '');
    x.ch = X && !x.etfOnly && !x.fund && !nonStk ? X.chain(x.sym) : null; x.pu = x.ch && X.pulse ? X.pulse(x.sym) : null; x.gmk = mk; x.s = x.ch ? Pq[x.ch[1]] + Pq[x.ch[2]] : 0; x.y = X && !x.fund && !x.etfOnly ? X.yoy(x.sym) : null; });
  // 22 Nov 2026 (Amritpal: "sort stocks as per quadrant strength"): industry + stock quadrant first (Leading > Improving >
  // Weakening > Lagging), then the stock's own quadrant, then buy / breakout, then the tested order
  rows.sort((a, b) => (b.nsys || 0) - (a.nsys || 0) || (b.buy ? 1 : 0) - (a.buy ? 1 : 0) || pulseSort(a, b) || b.s - a.s || (b.ch ? Pq[b.ch[2]] : -1) - (a.ch ? Pq[a.ch[2]] : -1) || (b.buy ? 1 : 0) - (a.buy ? 1 : 0) || (b.pri || 0) - (a.pri || 0) || (b.sc || 0) - (a.sc || 0));
  const seg = s.nse ? '' : `<div class="t3-mk" role="tablist" aria-label="Market">${[['NSE', 'India'], ['US', 'US'], ['ASX', 'Australia'], ['UK', 'UK']].map(([m, n]) => `<button data-ymk="${m}" role="tab" aria-selected="${mk === m}">${n}</button>`).join('')}</div>`;
  const nBuy = rows.filter((x) => x.buy).length;
  $('#sheet-body').innerHTML = `<div class="t3">${x3Trail([{ t: 'Search', go: () => searchOpen(), done: true }, { t: s.name, on: true }])}
    <div class="t3w-h"><div><h2 style="font-family:var(--font-head);margin:0">${esc(s.name)}</h2><small class="muted">${esc(s.d)}${s.ok ? '' : ' · watch only'}</small></div></div>
    ${seg}
    <div class="t3-rules"><button class="t3-rule" data-flt="all"><b>${rows.length}</b><small>${s.id === 'rot' || s.id === 'etf' ? 'ETFs' : 'stocks'} on it</small></button><button class="t3-rule" data-flt="buy"><b class="up">${nBuy}</b><small>buy / breakout now · tap to show</small></button></div>
    ${rows.some((x) => x.ch) ? `<div class="t3-key" aria-hidden="true">${['L', 'I', 'W', 'G'].map((k) => `<span><i style="background:${T3C[k]}"></i>${T3N[k]}</span>`).join('')}</div>` : ''}
    <ol class="st-list">${rows.slice(0, 150).map((x, i) => `<li data-fk="${x.buy ? 'buy' : ''}"><button class="st-row" data-yi="${i}"><span class="st-rk">${i + 1}</span><span class="st-nm"><b>${esc(x.sym)}</b><small class="${x.buy ? 'up' : ''}">${esc(x.st)}</small></span>${x.ch ? t3Bars(x.ch, true) : `<span class="muted">${esc(x.name || '')}</span>`}<span class="st-y">${pulsePill(x)}${x.ch ? t3Yoy(x.y) : ''}</span></button></li>`).join('') || `<li class="empty">Nothing on ${esc(s.name)} in ${esc(MKT[mk].name)} today.</li>`}</ol>
    ${rows.length > 150 ? `<p class="muted">Showing the first 150 of ${rows.length}.</p>` : ''}
    <p class="t3-foot">${s.id === 'grp' ? 'Stocks on at least one of our systems first (most systems, then buy signals), then the rest of the group. Pulse = share of the group\'s liquid stocks trending (1 month); rotation = the group vs Nifty this week. Context - the systems decide the buy. ' : ''}${s.id === 'gov' ? 'Only stocks on at least one of our systems (type "govt all" to see everyone), most systems first, buy signals first, then industry Pulse. Tested 2016-26 (26,644 signals): 3+ systems won 61% (next 3 months, median +5.3%) vs 54% (+1.9%) for one - but the average return was about the same and the last year was flat for all, so read the order as a tilt. A tight base or flag together with another system helped most; 9/21 with a 52-week base breakout did worse. Govt focus and news are context - the systems decide the buy. ' : ''}From the last nightly scans. Sorted by industry Pulse: top-10% Pulse industries that are also Leading or Improving first (tested best), then the rest by Pulse. Order is for reading only; it does not change what any system buys.</p></div>`;
  const root = $('#sheet-body');
  x3TrailWire(root, [{ t: 'Search', go: () => searchOpen() }, { t: s.name }]);
  root.querySelectorAll('[data-ymk]').forEach((b) => b.addEventListener('click', () => sysListView(s, b.dataset.ymk, q))); tileFilter(root);
  root.querySelectorAll('[data-yi]').forEach((b) => b.addEventListener('click', () => { const x = rows[+b.dataset.yi];
    if (x.fl) return patternView(x.fl, mk);
    if (x.asset) return window.open('https://www.tradingview.com/chart/?symbol=' + encodeURIComponent(tvOf(x.asset.key)) + '&interval=' + (s.id === 'mo' ? '1M' : s.id === 'wk' ? '1W' : 'D'), '_blank', 'noopener');
    if (x.pt && x.pt.kind && x.pt.kind !== 'stock') return bottomView(x.pt, mk);
    if (x.fund) return fundSelect(x.fund);
    if (x.etfOnly) return sysCheck({ mk, sym: x.sym, name: x.name || x.sym, kind: 'ETF' });
    stockPage({ mk, sym: x.sym, name: x.name || x.sym, kind: 'stock' }, [{ t: 'Search', go: () => searchOpen(), done: true }, { t: s.name, go: () => sysListView(s, mk, q), done: true }, { t: x.sym, on: true }]); }));
}

/* ------------------------------------------------------------------ Back steps through sheets (22 Nov 2026)
   Amritpal: "When I go back from search it lands on today page rather than search". Every panel used to replace the one before
   and Back closed them all. Now each new panel keeps the previous one (its live nodes, so taps and typed text still work) and
   Back (phone back, the X, Esc) returns to it: Search -> system list -> stock -> back -> list -> back -> search -> back -> page.
   Loading placeholders are skipped; a second push for the same panel (some screens pushed twice) is ignored. */
(function () {
  const body = document.getElementById('sheet-body'); if (!body || SH.obs) return;
  SH.obs = new MutationObserver((recs) => { SH.buf.push(...recs); }); SH.obs.observe(body, { childList: true });
  const isPh = (nodes) => { const el = nodes.filter((n) => n.nodeType === 1); return el.length === 1 && el[0].matches && el[0].matches('p.pad, p.muted.pad'); };
  const push0 = history.pushState.bind(history);
  history.pushState = function (st, t, u) {
    if (!(st && st.sheet)) return push0(st, t, u);
    const recs = SH.buf.concat(SH.obs.takeRecords()); SH.buf = [];
    const rem = recs.filter((r) => r.removedNodes.length).map((r) => Array.from(r.removedNodes)).filter((L) => L.some((n) => n.nodeType === 1 || (n.textContent || '').trim()));
    const prev = rem.length ? rem[rem.length - 1] : null;
    if (prev && !isPh(prev) && SH.depth > 0) { SH.stack.push(prev); SH.depth++; return push0(st, t, u); }
    if (SH.depth > 0 && !$('#sheet').hidden) return undefined;          // same panel pushed twice / placeholder swap: no new step
    SH.stack = []; SH.depth = 1; return push0(st, t, u);
  };
})();
function sheetBack() {
  if (!$('#sheet').hidden && SH.stack.length) {
    const nodes = SH.stack.pop(); SH.depth = Math.max(0, SH.depth - 1);
    const body = $('#sheet-body'); body.replaceChildren(...nodes); SH.buf = []; try { SH.obs.takeRecords(); } catch (e) { /* */ }
    body.scrollTop = 0; const sh = $('#sheet'); if (sh) sh.scrollTop = 0; return;
  }
  closeSheet();
}

/* Bottom pattern chart for an index or asset (22 Nov 2026, Amritpal: "include all assets including indices in patterns"):
   the lows, neckline, stop and the classic target on the same chart as the flags */
async function bottomView(x, mk) {
  const TYP = { DB: 'W bottom', TW: 'Tilted W', TB: 'Triple bottom', IHS: 'Inverse H&S' };
  const f = { symbol: x.symbol, name: x.name, kind: x.kind, shape: TYP[x.typ] || x.typ, status: x.status, trigger: x.neck, stop: x.stop, target: x.target,
    bo_date: x.signal_date, from: (x.lows[0] || [])[0], geo: {}, marks: (x.lows || []).map((l, i) => [l[0], l[1], x.typ === 'IHS' ? ['Left', 'Head', 'Right'][i] : 'Low ' + (i + 1)]),
    pole_pct: 0, risk_pct: x.stop_pct, flag_days: (x.lows || []).length, depth_pct: x.height_pct };
  const Mz = (v) => (mk === 'NSE' ? inr(v, 0) : `${MKT[mk].cur}${fmt(v, 2, MKT[mk].loc)}`).replace('₹', x.kind === 'stock' ? '₹' : '');
  openPanel(`<div class="t3"><div class="t3w-h"><div><h2 style="font-family:var(--font-head);margin:0">${esc(x.symbol)}</h2><small class="muted">${x.kind === 'index' ? 'Index' : 'Asset'} · ${esc(f.shape)} · ${x.status === 'breakout' ? 'broke above the neckline ' + esc(day(x.signal_date)) : fmt(x.to_neck_pct, 1) + '% below the neckline'}</small></div></div>
    <div id="pcbox" class="sp-chart"><p class="muted">Loading chart…</p></div>
    <div class="sp-why"><div class="ok"><b>${Mz(x.neck)}</b><small>neckline (breakout above)</small></div><div class="bad"><b>${Mz(x.stop)}</b><small>below the lows</small></div><div class="ok"><b>${Mz(x.target)}</b><small>target (height added)</small></div></div>
    <p class="t3-note warn">Watch only: bottom patterns did no better than random in our stock tests; not tested on indices or assets.</p>
    <div class="sp-cbar"><a class="sp-tv" target="_blank" rel="noopener" href="https://www.tradingview.com/chart/?symbol=${encodeURIComponent(x.symbol)}">Open in TradingView ↗</a></div></div>`);
  const fp = encodeURIComponent(x.symbol.replace(/ /g, '_'));
  let S = null; try { const r = await fetch(fresh(MAIN + MKT[mk].path + 'pattern_charts/' + fp + '.json')); S = r.ok ? await r.json() : null; } catch (e) { /* */ }
  const box = $('#pcbox'); if (box) box.innerHTML = S && S.t ? patternSvg(S, f) : '<p class="muted">No chart stored yet (it appears after the next scan).</p>';
}

/* 22 Nov 2026 (Amritpal: "rank by Pulse"; rotation + Pulse test, claude/rotation-plus-pulse-test.md): lists read strongest
   industry Pulse first. Top tier = industry in the top 10% by Pulse AND Leading / Improving (tested best: 45.6%/yr as a basket vs
   36.9% for top-10% Pulse alone; strong Pulse while Weakening / Lagging did worse, 28.1%). Display order only. */
function pulseTier(x) { const p = x.pu; if (!p || p.p == null) return 0; const top = p.pct >= 0.9, li = ['L', 'I'].includes(p.q); return top && li ? 3 : top ? 2 : p.pct >= 0.5 ? 1 : 0; }
function pulseSort(a, b) { return pulseTier(b) - pulseTier(a) || ((b.pu && b.pu.p) || 0) - ((a.pu && a.pu.p) || 0); }
function pulsePill(x) { const p = x.pu; if (!p || p.p == null) return ''; const t = pulseTier(x);
  return `<span class="t3-pill ${t === 3 ? 'ok' : t === 2 ? 'warn' : ''}" title="Industry Pulse: share of the industry's stocks trending (1 month)">Pulse ${fmt(p.p, 0)}${t === 3 ? ' · top 10% + rotation' : t === 2 ? ' · top 10%' : ''}</span>`; }

/* 22 Nov 2026 (Amritpal, after the PM's FICCI speech: "link these to stocks and put a chip" -> "Govt focus"): stocks in the industries
   the government is pushing (data/scan/govt_focus.json, hand-kept, NSE basic industries) get a "Govt focus" chip; "· MSME" when the
   company's last full-year sales are up to Rs 500 cr (fundamentals). A theme to know about, not a buy signal - nothing here was tested. */
async function govLoad() {
  if (state.gov === undefined) { const [G, F, , N] = await Promise.all([getJSON(MAIN + 'data/scan/govt_focus.json', 'govt_focus').catch(() => null), getJSON(MAIN + MKT.NSE.path + 'fundamentals.json', 'fund_NSE').catch(() => null), loadGP('NSE').catch(() => null),
      getJSON(MAIN + 'data/scan/news_clues.json', 'news_clues').catch(() => null)]);
    state.gov = G || { themes: [] }; state.govF = (F && F.s) || {};
    // 22 Nov 2026 news clues (tools/news_clues.py): government / regulator actions per NSE industry, last 30 days
    const cut = new Date(Date.now() - 30 * 864e5).toISOString().slice(0, 10); state.govN = {};
    ((N && N.items) || []).filter((x) => x.date >= cut).forEach((x) => x.industries.forEach((i) => { (state.govN[i] = state.govN[i] || []).push(x); })); }
  return state.gov;
}
const govThemes = (basic) => ((state.gov && state.gov.themes) || []).filter((t) => (t.industries || []).includes(basic));
const govNews = (basic) => ((state.govN || {})[basic] || []);
function govOf(sym) {
  if (!state.gov) return null; const n = nseInd(state.gp.NSE, sym); if (!n) return null; const th = govThemes(n.basic); const nw = govNews(n.basic); if (!th.length && !nw.length) return null;
  const f = (state.govF || {})[sym]; const a = f && f.a && f.a.find((y) => y[3] != null); const cr = a ? a[3] / 1e7 : null;
  return { th, nw, cr, msme: cr != null && cr <= (state.gov.msme_sales_cr || 500) };
}
function govChip(sym, mk) {
  if ((mk || 'NSE') !== 'NSE') return ''; const g = govOf(sym); if (!g) return '';
  return `<span class="chip gov" title="Govt focus: ${esc(g.th.map((t) => t.name).concat(g.nw.slice(0, 2).map((x) => x.title)).join(' | '))}${g.msme ? ` · MSME-sized (sales ${inr(g.cr, 0)} cr)` : ''} - a theme, not a buy signal">Govt focus${g.nw.length ? ' · news' : ''}${g.msme ? ' · MSME' : ''}</span>`;
}
{ const PP = pulsePill; pulsePill = (x) => PP(x) + (x && x.sym && x.gmk === 'NSE' ? govChip(x.sym, 'NSE') + oiChip(x.sym) : ''); }
{ const PC = pulseChip; pulseChip = (sym, mk) => PC(sym, mk) + ((mk || AM()) === 'NSE' ? govChip(sym, 'NSE') : ''); }

/* Pulse rotation forward test (22 Nov 2026): equal weight, Friday close to Friday close, no costs - a paper mark */
function prFwd(P) { const M = P && P.mark;
  if (M && M.since) return `paper basket from the ${day(M.since)} close: ${M.ret >= 0 ? '+' : ''}${fmt(M.ret, 1)}% vs Nifty ${M.nifty >= 0 ? '+' : ''}${fmt(M.nifty, 1)}% (marked ${day(M.date)}; this week ${M.week >= 0 ? '+' : ''}${fmt(M.week, 1)}%${M.closed ? ` · ${M.closed} sold, avg ${M.closed_ret >= 0 ? '+' : ''}${fmt(M.closed_ret, 1)}%` : ''})`;
  const L = (P && P.ledger) || []; if (L.length < 2) return 'started, first result next Friday';
  const a = L[L.length - 1]; const r = (a.equity - 1) * 100, n = ((a.nifty_eq || 1) - 1) * 100;
  return `${r >= 0 ? '+' : ''}${fmt(r, 1)}% vs Nifty ${n >= 0 ? '+' : ''}${fmt(n, 1)}% over ${L.length - 1} week${L.length === 2 ? '' : 's'}`; }

/* 22 Nov 2026 morning check: the industry's opening move (NSE pre-open price vs yesterday's close), read by the server at 09:09.
   Rule rows (9/21 any stock, Pulse rotation) skip when it is red - tested; for other systems it is information only. */
function mornChip(r) { const m = r.morning; if (!m || m.gap == null) return '';
  const up = m.gap > 0;
  return `<div class="lv-sub"><span class="chip ${up ? 'new' : 'exit'}" title="Industry ${esc(m.ind)}: average opening move of its liquid stocks vs yesterday's close (09:09 pre-open price)">${esc(m.ind)} opened ${m.gap >= 0 ? '+' : ''}${fmt(m.gap, 2)}%${m.rule ? (up ? ' · morning check OK' : ' · morning check: skip') : ' · info (rule not tested for this system)'}</span></div>`; }
